$currentCustomerGroups=[];$rowGroupKeys=[];$baseToCustomer=[];
$normalizeCustomerKey=function(string $name): string {
    $name=preg_replace('/\s+/u',' ',trim($name))??trim($name);
    $base=preg_replace('/\s*[0-9۰-۹٠-٩]+\s*$/u','',$name)??$name;
    $base=strtr($base,['ي'=>'ی','ى'=>'ی','ك'=>'ک','أ'=>'ا','إ'=>'ا','آ'=>'ا']);
    $base=preg_replace('/[^\pL\pN]+/u','',$base)??$base;
    return function_exists('mb_strtoupper')?mb_strtoupper($base,'UTF-8'):strtoupper($base);
};
$baseDisplayName=function(string $name): string {$name=preg_replace('/\s+/u',' ',trim($name))??trim($name);$base=preg_replace('/\s*[0-9۰-۹٠-٩]+\s*$/u','',$name)??$name;return trim($base)!==''?trim($base):$name;};
foreach($savedReport['rows'] as $rr){
    if(!empty($rr['autogroup_excluded']))continue;
    $label=(string)($rr['display_name_snapshot']?:($rr['original_name_snapshot']?:$rr['source_username']));$bk=$normalizeCustomerKey($label);
    if($bk!==''&&!empty($rr['customer_id']))$baseToCustomer[$bk]=(int)$rr['customer_id'];
}
foreach($savedReport['rows'] as $idx=>$rr){
    $label=(string)($rr['display_name_snapshot']?:($rr['original_name_snapshot']?:$rr['source_username']));$bk=$normalizeCustomerKey($label);
    if(!empty($rr['autogroup_excluded']))$gk='row:'.($rr['account_id']?:$rr['source_username']).':'.$idx;
    elseif(!empty($rr['customer_id']))$gk='customer:'.(int)$rr['customer_id'];
    elseif($bk!==''&&isset($baseToCustomer[$bk]))$gk='customer:'.$baseToCustomer[$bk];
    else {$uk=(string)$rr['source_username'];$uk=function_exists('mb_strtoupper')?mb_strtoupper($uk,'UTF-8'):strtoupper($uk);$gk='name:'.($bk!==''?$bk:$uk);}
    $rowGroupKeys[$idx]=$gk;
    if(!isset($currentCustomerGroups[$gk])){$name=!empty($rr['customer_name'])?(string)$rr['customer_name']:$baseDisplayName($label);$currentCustomerGroups[$gk]=['id'=>$gk,'name'=>$name,'rows'=>[]];}
    $currentCustomerGroups[$gk]['rows'][]=$rr;
}
