<script>
const reportCustomerGroups=<?=json_encode($currentCustomerGroups,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;
let activeReportCustomer=null,activeCustomerBlob=null,activeCustomerUrl=null;
const REPORT_MONEY_FACTOR=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>;
const REPORT_MONEY_LOCALE=<?=json_encode($uiSettings['digit_mode']==='fa'?'fa-IR':'en-US')?>;
const REPORT_SOURCE_LABEL='گزارش '+<?=json_encode(AccountingService::displayBusinessDate((string)$savedReport['report_date']),JSON_UNESCAPED_UNICODE)?>;
const REPORT_DISPLAY_DATE=<?=json_encode(AccountingService::displayBusinessDate((string)$savedReport['report_date']),JSON_UNESCAPED_UNICODE)?>;
const REPORT_MONEY_UNIT=<?=json_encode(SettingsService::moneyUnit($uiSettings),JSON_UNESCAPED_UNICODE)?>;
const REPORT_COLORS={recv:<?=json_encode($uiSettings['theme_recv']??'#ff5d60')?>,pay:<?=json_encode($uiSettings['theme_pay']??'#92cdd9')?>,comm:<?=json_encode($uiSettings['theme_comm']??'#78fa70')?>};
const moneyFmt=v=>{const n=(Number(v)||0)/REPORT_MONEY_FACTOR;return n.toLocaleString(REPORT_MONEY_LOCALE,{maximumFractionDigits:2})};
const dollarFmt=v=>{const n=Math.round((Number(v)||0)*100)/100;return n.toLocaleString('en-US',{minimumFractionDigits:0,maximumFractionDigits:2})};
function customerCalc(g){const t=g.rows.reduce((a,r)=>(a.received+=Number(r.received)||0,a.paid+=Number(r.paid)||0,a.commission+=Number(r.commission)||0,a),{received:0,paid:0,commission:0});t.net=t.received-t.paid;return t}
function customerText(g,t){const lines=[`حساب ${g.name}`,REPORT_SOURCE_LABEL,`مبالغ به ${REPORT_MONEY_UNIT}`];for(const r of g.rows){lines.push(`${r.display_name_snapshot||r.original_name_snapshot||r.source_username} — ${r.source_username}`);if(Number(r.member_win)<0)lines.push(`باخت: ${dollarFmt(Math.abs(Number(r.member_win)))} دلار | درصد مشتری: ${moneyFmt(r.commission)} | دریافتی: ${moneyFmt(r.received)}`);else if(Number(r.member_win)>0)lines.push(`برد: ${dollarFmt(r.member_win)} دلار | پرداختی: ${moneyFmt(r.paid)}`);else lines.push('برد و باخت: صفر')}lines.push(`جمع دریافتی: ${moneyFmt(t.received)}`,`جمع پرداختی: ${moneyFmt(t.paid)}`,`درصد مشتری: ${moneyFmt(t.commission)}`,(t.net>0?'دریافت از مشتری: ':t.net<0?'پرداخت به مشتری: ':'تسویه: ')+moneyFmt(Math.abs(t.net)));return lines.join('\n')}
function openReportCustomer(id){const g=reportCustomerGroups[id];if(!g)return;activeReportCustomer=g;const t=customerCalc(g);document.getElementById('reportCustomerTitle').textContent='حساب '+g.name;document.getElementById('reportCustomerReportLabel').textContent=REPORT_SOURCE_LABEL;document.getElementById('reportCustomerUnit').textContent=REPORT_MONEY_UNIT+(REPORT_MONEY_FACTOR===1000?'؛ سه صفر حذف شده است':REPORT_MONEY_FACTOR===10000?'؛ چهار صفر حذف شده است':'');const body=document.getElementById('reportCustomerRows');body.innerHTML=g.rows.map(r=>`<tr><td class="name-cell">${htmlEscape(r.display_name_snapshot||r.original_name_snapshot||r.source_username)}</td><td class="username-cell" dir="ltr">${htmlEscape(r.source_username)}</td><td class="comm-cell">${moneyFmt(r.commission)}</td><td>${Number(r.member_win)<0?dollarFmt(Math.abs(Number(r.member_win))):''}</td><td class="recv-cell">${moneyFmt(r.received)}</td><td>${Number(r.member_win)>0?dollarFmt(r.member_win):''}</td><td class="pay-cell">${moneyFmt(r.paid)}</td></tr>`).join('');document.getElementById('reportCustomerTotals').innerHTML=`<div class="pay-cell"><span>جمع پرداختی</span><b>${moneyFmt(t.paid)}</b></div><div class="comm-cell"><span>درصد مشتری</span><b>${moneyFmt(t.commission)}</b></div><div class="recv-cell"><span>جمع دریافتی</span><b>${moneyFmt(t.received)}</b></div>`;const bal=document.getElementById('reportCustomerBalance');bal.className='customer-reference-balance '+(t.net>0?'recv-cell':t.net<0?'pay-cell':'comm-cell');bal.innerHTML=`<b>${t.net>0?'دریافت از مشتری':t.net<0?'پرداخت به مشتری':'تسویه'}: ${moneyFmt(Math.abs(t.net))}</b>`;document.getElementById('reportCustomerFallback').classList.add('hidden');document.getElementById('reportCustomerShareStatus').textContent='در حال آماده‌سازی عکس…';openAppDialog('reportCustomerDialog');requestAnimationFrame(()=>buildReportCustomerImage(g,t));}
function htmlEscape(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
async function buildReportCustomerImage(g,t){if(document.fonts)await document.fonts.ready;const w=1400,rowH=74,top=156,h=400+g.rows.length*rowH,c=document.createElement('canvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.direction='rtl';x.textAlign='center';x.textBaseline='middle';const txt=(value,cx,cy,width,font=22,color='#000',dir='rtl')=>{x.font=`bold ${font}px Vazirmatn, Tahoma, Arial, sans-serif`;x.fillStyle=color;x.direction=dir;x.fillText(String(value),cx,cy,width-10)};txt('حساب '+g.name,700,45,1300,36);txt(REPORT_SOURCE_LABEL,700,90,1300,19,'#555','ltr');txt(`مبالغ به ${REPORT_MONEY_UNIT}${REPORT_MONEY_FACTOR===1000?'؛ سه صفر حذف شده است':REPORT_MONEY_FACTOR===10000?'؛ چهار صفر حذف شده است':''}`,700,124,1300,23);const widths=[304,224,168,168,168,168,168],starts=[];let right=1384;for(const ww of widths){right-=ww;starts.push(right)}const box=(left,yy,width,height,color,value,font=22,ink='#000',dir='rtl')=>{x.fillStyle=color;x.fillRect(left,yy,width,height);x.strokeStyle='#222';x.lineWidth=1.4;x.strokeRect(left,yy,width,height);txt(value,left+width/2,yy+height/2,width,font,ink,dir)};box(starts[1],top,widths[0]+widths[1],48,'#fff','مشخصات مشتری',26);box(starts[4],top,widths[2]+widths[3]+widths[4],48,'#fff','دریافتی (باخت مشتری)',26);box(starts[6],top,widths[5]+widths[6],48,'#fff','پرداختی (برد مشتری)',26);['نام مشتری','نام کاربری','درصد مشتری','به دلار','به تومان','به دلار','به تومان'].forEach((v,i)=>box(starts[i],top+48,widths[i],48,'#fff',v,21));g.rows.forEach((r,ri)=>{const vals=[r.display_name_snapshot||r.original_name_snapshot||r.source_username,r.source_username,moneyFmt(r.commission),Number(r.member_win)<0?dollarFmt(Math.abs(Number(r.member_win))):'',moneyFmt(r.received),Number(r.member_win)>0?dollarFmt(r.member_win):'',moneyFmt(r.paid)];vals.forEach((v,i)=>box(starts[i],top+96+ri*rowH,widths[i],rowH,i===2?REPORT_COLORS.comm:i===4?REPORT_COLORS.recv:i===6?REPORT_COLORS.pay:'#fff',v,i===0?22:i===1?19:25,'#000',i===1||i===3||i===5?'ltr':'rtl'))});const y=top+108+g.rows.length*rowH;box(16,y,430,48,REPORT_COLORS.pay,'جمع پرداختی: '+moneyFmt(t.paid),23);box(446,y,430,48,REPORT_COLORS.comm,'درصد مشتری: '+moneyFmt(t.commission),23);box(876,y,508,48,REPORT_COLORS.recv,'جمع دریافتی: '+moneyFmt(t.received),23);box(16,y+48,1368,66,t.net>0?REPORT_COLORS.recv:t.net<0?REPORT_COLORS.pay:REPORT_COLORS.comm,(t.net>0?'دریافت از مشتری: ':t.net<0?'پرداخت به مشتری: ':'تسویه: ')+moneyFmt(Math.abs(t.net)),30);const blob=await new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('ساخت عکس انجام نشد.')),'image/png'));activeCustomerBlob=blob;if(activeCustomerUrl)URL.revokeObjectURL(activeCustomerUrl);activeCustomerUrl=URL.createObjectURL(blob);const img=document.getElementById('reportCustomerImage');img.src=activeCustomerUrl;const dl=document.getElementById('reportCustomerDownload');dl.href=activeCustomerUrl;dl.download='hesab-'+String(g.rows[0]?.source_username||'customer').replace(/[^a-zA-Z0-9_-]/g,'')+'.png';const fdl=document.getElementById('reportCustomerFallbackDownload');fdl.href=activeCustomerUrl;fdl.download=dl.download;document.getElementById('reportCustomerShareStatus').textContent='عکس آماده است.';}
async function shareReportCustomer(target){if(!activeReportCustomer)return;const t=customerCalc(activeReportCustomer),text=customerText(activeReportCustomer,t);if(!activeCustomerBlob){document.getElementById('reportCustomerShareStatus').textContent='تصویر هنوز آماده نشده؛ یک لحظه دوباره بزن.';return}try{if(navigator.share){const f=new File([activeCustomerBlob],document.getElementById('reportCustomerDownload').download||'customer-account.png',{type:'image/png'});if(!navigator.canShare||navigator.canShare({files:[f]})){await navigator.share({files:[f],title:'حساب '+activeReportCustomer.name,text});return}}}catch(e){if(e&&e.name==='AbortError')return}showReportCustomerFallback(text,target)}
function showReportCustomerFallback(text,target){const box=document.getElementById('reportCustomerFallback');box.classList.remove('hidden');document.getElementById('reportCustomerFallbackText').value=text;document.getElementById('reportCustomerWaText').href='https://wa.me/?text='+encodeURIComponent(text);document.getElementById('reportCustomerTgText').href='https://t.me/share/url?url=&text='+encodeURIComponent(text);if(target==='whatsapp')window.open(document.getElementById('reportCustomerWaText').href,'_blank');else if(target==='telegram'){navigator.clipboard?.writeText(text);window.open('https://t.me/','_blank')}document.getElementById('reportCustomerShareStatus').textContent='اگر مرورگر فایل را مستقیم Share نکرد، عکس را دریافت و پیوست کن؛ متن حساب هم آماده است.'}
async function copyReportCustomerText(){if(!activeReportCustomer)return;const text=customerText(activeReportCustomer,customerCalc(activeReportCustomer));try{await navigator.clipboard.writeText(text);document.getElementById('reportCustomerShareStatus').textContent='متن حساب کپی شد.'}catch(e){const a=document.getElementById('reportCustomerFallbackText');a.value=text;a.classList.remove('hidden');a.select();document.getElementById('reportCustomerShareStatus').textContent='متن را از کادر انتخاب و کپی کن.'}}
</script>
