<script>
(()=>{
let rows=<?=json_encode($draft['rows'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let editing=-1;
const n=v=>{const s=String(v??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/,/g,'');const x=Number(s);return Number.isFinite(x)?x:0};
const MONEY_FACTOR=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>;const fd=v=>{const x=Math.round((Number(v)||0)*1e6)/1e6;return x.toLocaleString('en-US',{maximumFractionDigits:6})};const fm=v=>((Number(v)||0)/MONEY_FACTOR).toLocaleString('en-US',{maximumFractionDigits:2});const rateDisplay=v=>((Number(v)||0)/MONEY_FACTOR);const rateCanonical=v=>(Number(v)||0)*MONEY_FACTOR;
function calc(r){const mw=n(r.member_win),rate=n(r.rate),pct=n(r.loss_percent);let commission=0,received=0,paid=0;if(mw<0){const gross=Math.abs(mw)*rate;commission=gross*pct/100;received=gross-commission}else if(mw>0)paid=mw*rate;r.member_win=mw;r.rate=rate;r.loss_percent=pct;r.commission=commission;r.received=received;r.paid=paid;return r}
function totals(){return rows.reduce((t,r)=>{calc(r);t.received+=r.received;t.paid+=r.paid;t.commission+=r.commission;return t},{received:0,paid:0,commission:0})}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
function render(){const body=document.getElementById('previewRows');body.innerHTML=rows.map((r,i)=>{calc(r);const unresolved=!r.account_id&&!r.unknown_confirmed;return `<tr class="${!r.account_id?'unknown-row':''} ${unresolved?'unresolved-row':''}"><td class="name-cell">${esc(r.name||r.username)}</td><td class="username-cell" dir="ltr">${esc(r.username)}</td><td class="comm-cell">${r.commission?fm(r.commission):''}</td><td>${r.member_win<0?fd(Math.abs(r.member_win)):''}</td><td class="recv-cell">${r.received?fm(r.received):''}</td><td>${r.member_win>0?fd(r.member_win):''}</td><td class="pay-cell">${r.paid?fm(r.paid):''}</td><td><button type="button" class="ghost row-edit" data-i="${i}">✎</button></td></tr>`}).join('');const t=totals(),net=t.received-t.paid,status=net>0?'برد سایت':net<0?'باخت سایت':'تسویه',cls=net>0?'site-win':net<0?'site-loss':'comm-cell';document.getElementById('previewTotals').innerHTML=`<div class="recv-cell"><span>دریافتی</span><b>${fm(t.received)}</b></div><div class="pay-cell"><span>پرداختی</span><b>${fm(t.paid)}</b></div><div class="comm-cell"><span>کمیسیون</span><b>${fm(t.commission)}</b></div><div class="${cls}"><span>${status}</span><b>${fm(Math.abs(net))}</b></div>`;body.querySelectorAll('.row-edit').forEach(b=>b.onclick=()=>openRow(Number(b.dataset.i)));const u=rows.filter(r=>!r.account_id&&!r.unknown_confirmed);const list=document.getElementById('unknownList');if(list)list.innerHTML=u.map(r=>`<div><b dir="ltr">${esc(r.username)}</b><span>${esc(r.name||'')}</span></div>`).join('')}
function openRow(i){editing=i;const r=rows[i];document.getElementById('rowEditorTitle').textContent=i<0?'افزودن ردیف':'ویرایش ردیف';document.getElementById('editUsername').value=r?.username||'';document.getElementById('editName').value=r?.name||'';document.getElementById('editOutcome').value=!r||r.member_win===0?'zero':r.member_win<0?'loss':'win';document.getElementById('editAmount').value=r?Math.abs(n(r.member_win)):'';document.getElementById('editRate').value=r?rateDisplay(r.rate):rateDisplay(<?=json_encode($draft['general_rate'])?>);document.getElementById('editPct').value=r?.loss_percent??<?=json_encode($draft['loss_percent'])?>;document.getElementById('editPanel').value=r?.panel_id||'';document.getElementById('editRegister').checked=!!r?.register_manual;document.getElementById('deleteRowBtn').style.display=i<0?'none':'';syncPct();openAppDialog('rowEditor')}
function syncPct(){const win=document.getElementById('editOutcome').value!=='loss';document.getElementById('editPct').disabled=win}
document.getElementById('editOutcome').onchange=syncPct;document.getElementById('addReportRowBtn').onclick=()=>openRow(-1);document.getElementById('saveRowBtn').onclick=()=>{const outcome=document.getElementById('editOutcome').value,amount=Math.abs(n(document.getElementById('editAmount').value));const old=editing>=0?rows[editing]:{};const r={...old,username:document.getElementById('editUsername').value.trim(),name:document.getElementById('editName').value.trim(),member_win:outcome==='loss'?-amount:outcome==='win'?amount:0,rate:rateCanonical(document.getElementById('editRate').value),loss_percent:n(document.getElementById('editPct').value),panel_id:document.getElementById('editPanel').value||null,register_manual:document.getElementById('editRegister').checked,unknown_confirmed:old.account_id?true:(old.unknown_confirmed||document.getElementById('editRegister').checked)};if(!r.username){appAlert('Username الزامی است.');return;}if(!r.name)r.name=r.username;if(editing>=0)rows[editing]=r;else rows.push(r);closeAppDialog('rowEditor');render()};document.getElementById('deleteRowBtn').onclick=async()=>{if(editing>=0&&await appConfirm('این ردیف حذف شود؟',{danger:true,confirmText:'حذف'})){rows.splice(editing,1);closeAppDialog('rowEditor');render()}};
function unresolved(){return rows.filter(r=>!r.account_id&&!r.unknown_confirmed)}function payload(){return JSON.stringify({rows:rows.map(calc)})}const resolveBtn=document.getElementById('resolveUnknownBtn');if(resolveBtn)resolveBtn.onclick=()=>{render();openAppDialog('unknownResolver')};function resolveUnknown(register){const pid=document.getElementById('unknownPanel').value;if(!pid){appAlert('پنل این گزارش را انتخاب کن.');return;}rows=rows.map(r=>!r.account_id&&!r.unknown_confirmed?{...r,panel_id:pid,register_manual:register,unknown_confirmed:true}:r);closeAppDialog('unknownResolver');render()}const keepBtn=document.getElementById('keepUnknownTemporary');if(keepBtn)keepBtn.onclick=()=>resolveUnknown(false);const regBtn=document.getElementById('registerUnknownAccounts');if(regBtn)regBtn.onclick=()=>resolveUnknown(true);document.getElementById('finalizeReportBtn').onclick=()=>{if(unresolved().length){render();openAppDialog('unknownResolver');return}document.getElementById('finalDraftJson').value=payload();document.getElementById('finalizeReportForm').submit()};document.getElementById('backToEntryBtn').onclick=()=>{document.getElementById('backDraftJson').value=payload();document.getElementById('backDraftForm').submit()};render();
})();
</script>
