<0?'باخت سایت ':'تسویه ')).SettingsService::money(abs((float)$r['net']),$uiSettings))?></td><?php else:?><td><?=e(AccountingService::displayBusinessDate((string)$r['report_date']))?></td><td><?=e($r['company_name'])?></td><td><?=e($r['panel_name'])?></td><td class="recv-cell"><?=e(SettingsService::money($r['received'],$uiSettings))?></td><td class="pay-cell"><?=e(SettingsService::money($r['paid'],$uiSettings))?></td><td class="comm-cell"><?=e(SettingsService::money($r['commission'],$uiSettings))?></td><td class="<?=e($r['net']>0?'site-win':($r['net']<0?'site-loss':'comm-cell'))?>"><?=e(($r['net']>0?'برد سایت ':($r['net']<0?'باخت سایت ':'تسویه ')).SettingsService::money(abs((float)$r['net']),$uiSettings))?></td><td class="no-image report-actions-cell"><a class="report-view-icon" href="index.php?page=entry&report=<?=e($r['id'])?>" aria-label="مشاهده گزارش" title="مشاهده گزارش">👁</a></td><?php endif;?></tr><?php endforeach;?></tbody></table></div><canvas id="reportSummaryCanvas" hidden></canvas><div id="reportShareBox" class="share-box hidden"><a id="reportImageDownload" class="btn ghost" download="report.png">ذخیره تصویر</a><button class="primary" type="button" onclick="shareReportImage('any')">اشتراک تصویر</button><button class="ghost" type="button" onclick="shareReportImage('whatsapp')">واتساپ</button><button class="ghost" type="button" onclick="shareReportImage('telegram')">تلگرام</button></div><script>
const REPORT_THEME=<?=json_encode(['recv'=>SettingsService::themeFill($uiSettings['theme_recv'],$uiSettings),'pay'=>SettingsService::themeFill($uiSettings['theme_pay'],$uiSettings),'comm'=>SettingsService::themeFill($uiSettings['theme_comm'],$uiSettings),'siteWin'=>SettingsService::themeFill($uiSettings['theme_site_win']??$uiSettings['theme_pay'],$uiSettings),'siteLoss'=>SettingsService::themeFill($uiSettings['theme_site_loss']??$uiSettings['theme_recv'],$uiSettings)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let reportImageBlob=null;
async function makeReportImage(){const table=document.getElementById('reportDataTable');if(!table)return;const raw=[...table.rows].map(tr=>[...tr.cells].filter(td=>!td.classList.contains('no-image')&&!td.classList.contains('no-output')).map(td=>({text:td.innerText.trim(),recv:td.classList.contains('recv-cell'),pay:td.classList.contains('pay-cell'),comm:td.classList.contains('comm-cell'),siteWin:td.classList.contains('site-win'),siteLoss:td.classList.contains('site-loss'),head:td.tagName==='TH'})));if(raw.length>251){appAlert('این گزارش بیش از ۲۵۰ ردیف دارد؛ برای نسخه کامل از PDF استفاده کن.');return}if(document.fonts)await document.fonts.ready;const cols=Math.max(...raw.map(r=>r.length)),cw=Math.max(120,Math.floor(1500/cols)),w=cw*cols+40,rh=54,top=120,bottom=250,h=top+raw.length*rh+bottom,c=document.getElementById('reportSummaryCanvas');c.width=w;c.height=h;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,w,h);x.fillStyle='#111';x.textAlign='center';x.textBaseline='middle';x.font='bold 34px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText('گزارش سلطان حساب',w/2,40);x.font='18px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(<?=json_encode('واحد مبلغ: '.SettingsService::moneyUnit($uiSettings),JSON_UNESCAPED_UNICODE)?>,w/2,78);let y=top;for(const row of raw){let right=w-20;for(let i=0;i<cols;i++){right-=cw;const cell=row[i]||{text:''};x.fillStyle=cell.recv?REPORT_THEME.recv:cell.pay?REPORT_THEME.pay:cell.comm?REPORT_THEME.comm:cell.siteWin?REPORT_THEME.siteWin:cell.siteLoss?REPORT_THEME.siteLoss:cell.head?'#e2e8f0':'#fff';x.fillRect(right,y,cw,rh);x.strokeStyle='#111';x.lineWidth=2;x.strokeRect(right,y,cw,rh);x.fillStyle='#111';x.font=(cell.head?'bold 18px':'bold 16px')+' Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(cell.text,right+cw/2,y+rh/2,cw-10)}y+=rh}const t=<?=json_encode($reportData['totals'])?>,factor=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>,fmt=n=>(Number(n||0)/factor).toLocaleString(<?=json_encode($uiSettings['digit_mode']==='fa'?'fa-IR':'en-US')?>,{maximumFractionDigits:2}),net=Number(t.net)||0;const boxes=[['جمع پرداختی',t.paid,REPORT_THEME.pay],['جمع کمیسیون',t.commission,REPORT_THEME.comm],['جمع دریافتی',t.received,REPORT_THEME.recv]];const bw=(w-40)/3;boxes.forEach((b,i)=>{x.fillStyle=b[2];x.fillRect(20+i*bw,y+28,bw,62);x.strokeStyle='#111';x.strokeRect(20+i*bw,y+28,bw,62);x.fillStyle='#111';x.font='bold 20px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(`${b[0]}: ${fmt(b[1])}`,20+i*bw+bw/2,y+59,bw-12)});x.fillStyle=net>0?REPORT_THEME.siteWin:net<0?REPORT_THEME.siteLoss:REPORT_THEME.comm;x.fillRect(20,y+90,w-40,72);x.strokeStyle='#111';x.strokeRect(20,y+90,w-40,72);x.fillStyle='#111';x.font='bold 24px Vazirmatn,Tahoma,Arial,sans-serif';x.fillText(`${net>0?'برد سایت':net<0?'باخت سایت':'تسویه'}: ${fmt(Math.abs(net))}`,w/2,y+126,w-60);reportImageBlob=await new Promise(res=>c.toBlob(res,'image/png'));const url=URL.createObjectURL(reportImageBlob);const a=document.getElementById('reportImageDownload');if(a.dataset.url)URL.revokeObjectURL(a.dataset.url);a.dataset.url=url;a.href=url;document.getElementById('reportShareBox').classList.remove('hidden');}
async function shareReportImage(target){if(!reportImageBlob){await makeReportImage();if(!reportImageBlob)return}const text='گزارش سلطان حساب';try{if(navigator.share){const f=new File([reportImageBlob],'soltan-hesab-report.png',{type:'image/png'});if(!navigator.canShare||navigator.canShare({files:[f]})){await navigator.share({files:[f],title:text,text});return}}}catch(e){if(e&&e.name==='AbortError')return}if(target==='whatsapp')window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank');else{navigator.clipboard?.writeText(text);window.open('https://t.me/','_blank')}}
</script>

