?'selected':''?>>Vazirmatn</option><option value="iransans" <?=$s[$k]==='iransans'?'selected':''?>>IRANSans</option><option value="system" <?=$s[$k]==='system'?'selected':''?>>System / Tahoma</option></select></label><?php endforeach;?></div><div class="notice ok"><b>Vazirmatn برای همه دستگاه‌ها از WebFont بارگذاری می‌شود.</b><span>IRANSans فقط اگر فایل <code>assets/fonts/Iranian-Sans.ttf</code> روی هاست موجود باشد استفاده می‌شود؛ در غیر این صورت خودکار به Vazirmatn برمی‌گردد و درخواست 404 تولید نمی‌شود.</span></div></section><section class="card"><h2>تم</h2><div class="theme-grid"><?php foreach(['theme_bg'=>'پس‌زمینه','theme_card'=>'کارت','theme_text'=>'متن','theme_primary'=>'اصلی','theme_recv'=>'دریافتی','theme_pay'=>'پرداختی','theme_comm'=>'کمیسیون','theme_site_win'=>'برد سایت','theme_site_loss'=>'باخت سایت'] as $k=>$label):?><label><?=$label?><input type="color" name="<?=$k?>" value="<?=e($s[$k])?>"></label><?php endforeach;?><label>Opacity<input type="range" min="20" max="100" name="theme_opacity" value="<?=e($s['theme_opacity'])?>"></label></div><div class="theme-preview"><b>پیش‌نمایش</b><div class="preview-swatches"><span class="recv-cell">دریافتی</span><span class="pay-cell">پرداختی</span><span class="comm-cell">کمیسیون</span></div></div></section><button class="primary settings-save">ذخیره همه تنظیمات</button></form><script>(()=>{const sel=document.getElementById('moneyScaleSelect');if(!sel)return;const fields=[document.getElementById('settingsGeneralRate'),document.getElementById('settingsSpecialRate')];const factor=s=>s==='trim3'?1000:s==='trim4'?10000:1;let prev=sel.dataset.currentScale||sel.value;sel.addEventListener('change',()=>{const oldF=factor(prev),newF=factor(sel.value);for(const el of fields){if(!el)continue;const raw=String(el.value||'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/,/g,'');const n=Number(raw);if(Number.isFinite(n))el.value=String(Math.round((n*oldF/newF)*1e6)/1e6)}prev=sel.value});})();</script>

